 33	  async createNewLead(
 34	    createSmartleadDto: CreateSmartleadDto,
 35	  ): Promise<{ message: string }> {
 36	    try {
 37	      this.logger.log('Loading Smartlead Service: Create New Lead');
 38	      // Find OrgId by userId
 39	      const orgId = this.usersService.findOrgIdForUser(
 40	        createSmartleadDto.userId,
 41	      );
 42	      if (!orgId) {
 43	        throw new NotFoundException('User not found');
 44	      }
 45	      const smartleadOpportunity = new SmartleadOpportunity({
 46	        ...createSmartleadDto,
 47	        id: createSmartleadDto.leadId,
 48	        orgId,
 49	        createdAt: new Date().toISOString(),
 50	      });
 51	      // See if lead already exists
 52	      try {
 53	        const lead = await this.getLeadById({
 54	          id: createSmartleadDto.leadId,
 55	          orgId,
 56	        });
 57	        if (lead) {
 58	          return {
 59	            message: 'Lead already exists',
 60	          };
 61	        }
 62	      } catch (error) {
 63	        if (error instanceof NotFoundException) {
 64	          // Lead does not exist, so we can create it
 65	        } else {
 66	          throw error;
 67	        }
 68	      }
 69	      await this.datastoreService.store(
 70	        new StoreDataDto({
 71	          data: smartleadOpportunity,
 72	          context: { documentType: documentType.SMARTLEAD_OPPORTUNITY },
 73	        }),
 74	      );
 75	      return {
 76	        message: 'Lead created successfully',
 77	      };
 78	    } catch (error) {
 79	      this.logger.error('Error in Smartlead Service: Create New Lead');
 80	      this.logger.error(error);
 81	      this.logger.error(`${JSON.stringify(createSmartleadDto)} Input Data`);
 82	      throw error;
 83	    }
 84	  }
