114	  async getLeadByEmail({
115	    email,
116	    orgId,
117	  }: {
118	    email: string;
119	    orgId: string;
120	  }): Promise<SmartleadOpportunity> {
121	    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
122	    const cachedLead = await cacheManager.get(
123	      `getLeadByEmail-${orgId}-${email}`,
124	    );
125	    if (cachedLead) {
126	      this.logger.log(
127	        `Cached lead found for email: ${email} for org: ${orgId}`,
128	      );
129	      return JSON.parse(cachedLead);
130	    }
131	    this.logger.log(`Getting lead by email: ${email} for org: ${orgId}`);
132	    let res;
133	    try {
134	      res = await fetch(
135	        `https://server.smartlead.ai/api/v1/leads/?api_key=${apiKey}&email=${email}`,
136	      );
137	
138	      const data = await res.json();
139	      const {
140	        id: smartleadId,
141	        first_name,
142	        last_name,
143	        website,
144	        created_at,
145	      } = data;
146	      this.logger.log(`Got Response`);
147	      const clientId =
148	        await this.usersService.findSmartleadClientIdForOrg(orgId);
149	      if (!clientId) {
150	        throw new NotFoundException('Client ID not found');
151	      }
152	      const filteredLeadCampaignData = data.lead_campaign_data.filter(
153	        (c) => c.client_id === parseInt(clientId),
154	      );
155	      //append all history to emailHistory, sorted by timestamp
156	      const historyDataRes = await Promise.all(
157	        filteredLeadCampaignData.map(async (c) => {
158	          const historyRes = await fetch(
159	            `https://server.smartlead.ai/api/v1/campaigns/${c?.campaign_id}/leads/${smartleadId}/message-history?api_key=${apiKey}`,
160	          );
161	          const historyData = await historyRes.json();
162	          return { historyData, campaignId: c?.campaign_name };
163	        }),
164	      );
165	      this.logger.log(`Got History Data`);
166	      const emailHistory = historyDataRes.reduce(
167	        (acc, { historyData, campaignId }) => {
168	          historyData?.history.forEach((item) => {
169	            acc.push({
170	              body: item.email_body,
171	              timestamp: item.time,
172	              campaignId: campaignId,
173	              subject: item.subject,
174	              type: item.type,
175	            });
176	          });
177	          return acc;
178	        },
179	        [],
180	      ) as Array<{
181	        body: string;
182	        timestamp: string;
183	        campaignId: string;
184	        subject: string;
185	        type: string;
186	      }>;
187	      this.logger.log(`Got Email History Length: ${emailHistory?.length}`);
188	      const sortedEmailHistory = emailHistory.sort((a, b) => {
189	        return (
190	          new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
191	        );
192	      });
193	      const returnedLeadVal = {
194	        id: smartleadId,
195	        firstName: first_name,
196	        lastName: last_name,
197	        email: email,
198	        company: website,
199	        emailHistory: sortedEmailHistory,
200	        orgId,
201	        createdAt: created_at,
202	        campaigns: data.lead_campaign_data.map((c) => c.campaign_name),
203	      };
204	      this.logger.log(`Got Returned Lead Val`);
205	      await cacheManager.set(
206	        `getLeadByEmail-${orgId}-${email}`,
207	        JSON.stringify(returnedLeadVal),
208	        TTL_3_DAYS,
209	      );
210	      this.logger.log(`Set Cache for ${orgId} and ${email}`);
211	      return returnedLeadVal;
212	    } catch (error) {
213	      this.logger.error('Error in Smartlead Service: Get Lead By Email');
214	      this.logger.error(error);
215	      if (res) {
216	        this.logger.error(`Response: ${res.status}`);
217	        this.logger.error(`Response: ${res.statusText}`);
218	        try {
219	          this.logger.error(`Response: ${await res.text()}`);
220	        } catch (error) {
221	          this.logger.error(`Error getting response text: ${error}`);
222	        }
223	      }
224	      throw error;
225	    }
226	  }
