import { Logger } from '@nestjs/common';

export const SMARTLEAD_API_BASE_URL = 'https://server.smartlead.ai/api/v1';

/**
 * How healthy an inbox is, derived from the deliverability (warm up reputation)
 * score reported by Smartlead.
 */
export enum DeliverabilityScore {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

/**
 * The enum above is referenced by a handful of names across the code base and
 * the delivery-ops scripts, so we expose the same value under its aliases.
 */
export const DeliverabilityRating = DeliverabilityScore;
export type DeliverabilityRating = DeliverabilityScore;
export const Deliverability = DeliverabilityScore;
export type Deliverability = DeliverabilityScore;
export const DeliverabilityStatus = DeliverabilityScore;
export type DeliverabilityStatus = DeliverabilityScore;
export const DeliverabilityCategory = DeliverabilityScore;
export type DeliverabilityCategory = DeliverabilityScore;
export const DeliverabilityLevel = DeliverabilityScore;
export type DeliverabilityLevel = DeliverabilityScore;
export const EmailAccountDeliverability = DeliverabilityScore;
export type EmailAccountDeliverability = DeliverabilityScore;

/** Ordering of the deliverability buckets, best first. */
export const DELIVERABILITY_ORDER: Record<DeliverabilityScore, number> = {
  [DeliverabilityScore.High]: 4,
  [DeliverabilityScore.Medium]: 3,
  [DeliverabilityScore.Low]: 2,
  [DeliverabilityScore.Burned]: 1,
  [DeliverabilityScore.Unknown]: 0,
};

/** A perfectly warmed inbox. */
export const HIGH_DELIVERABILITY_SCORE = 100;
/** Anything from here up to (but excluding) a perfect score is medium. */
export const MEDIUM_DELIVERABILITY_SCORE = 98;
/** Anything from here up to (but excluding) medium is low. */
export const LOW_DELIVERABILITY_SCORE = 95;

export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;

export type EmailAccountLike = Partial<EmailAccount> & Record<string, any>;

/**
 * A warmed sending inbox that lives inside of Smartlead.
 *
 * The inbox is keyed by its Smartlead inbox id, keeps hold of the Smartlead
 * client (and therefore organization) it belongs to and tracks every campaign
 * it has been associated with.
 */
export class EmailAccount {
  private static readonly logger = new Logger(EmailAccount.name);

  /** Primary key. The id of the inbox inside of Smartlead. */
  smartleadInboxId: string;
  /** The Smartlead client (organization) the inbox has been provisioned for. */
  smartleadClientId: string;
  /** The address we send from. */
  email: string;
  /** Free form labels used by delivery ops. */
  tags: string[] = [];
  /** Every campaign the inbox is currently sending for. */
  campaignIds: string[] = [];
  /** The warm up reputation reported by Smartlead, as a percentage. */
  deliverabilityScore?: number;
  /** When the inbox was created inside of Smartlead. */
  createdAt?: string;
  updatedAt?: string;

  constructor(partial: EmailAccountLike = {}) {
    Object.assign(this, EmailAccount.unwrap(partial));
    // Mongo decorates documents with the collection they were read from.
    delete (this as any)._collection;
    delete (this as any)._id;
    this.smartleadInboxId = EmailAccount.normalizeId(this.smartleadInboxId);
    this.smartleadClientId = EmailAccount.normalizeId(this.smartleadClientId);
    this.tags = EmailAccount.normalizeList(this.tags);
    this.campaignIds = EmailAccount.normalizeList(this.campaignIds);
    const score = EmailAccount.parseScore(this.deliverabilityScore);
    if (score === undefined) {
      delete this.deliverabilityScore;
    } else {
      this.deliverabilityScore = score;
    }
    this.createdAt = EmailAccount.normalizeDate(this.createdAt);
    if (this.createdAt === undefined) {
      delete this.createdAt;
    }
  }

  /** Alias of {@link smartleadInboxId}: the inbox id is the document id. */
  get id(): string {
    return this.smartleadInboxId;
  }
  set id(id: string) {
    this.smartleadInboxId = EmailAccount.normalizeId(id);
  }

  /** The sending domain, derived from the email address. */
  get domain(): string {
    if (!this.email || typeof this.email !== 'string') {
      return undefined;
    }
    const [, domain] = this.email.trim().toLowerCase().split('@');
    return domain ? domain : undefined;
  }
  set domain(_domain: string) {
    // Derived from the email address, persisted values are ignored.
  }

  /** How many campaigns the inbox is currently sending for. */
  get numberOfCampaignAssociated(): number {
    return Array.isArray(this.campaignIds) ? this.campaignIds.length : 0;
  }
  set numberOfCampaignAssociated(_count: number) {
    // Derived from campaignIds, persisted values are ignored.
  }

  /** The deliverability bucket the inbox currently falls into. */
  get deliverability(): DeliverabilityScore {
    return EmailAccount.mapDeliverabilityScore(this.deliverabilityScore);
  }
  set deliverability(_deliverability: DeliverabilityScore) {
    // Derived from the deliverability score, persisted values are ignored.
  }

  get deliverabilityRating(): DeliverabilityScore {
    return this.deliverability;
  }
  set deliverabilityRating(_rating: DeliverabilityScore) {}

  get deliverabilityStatus(): DeliverabilityScore {
    return this.deliverability;
  }
  set deliverabilityStatus(_status: DeliverabilityScore) {}

  get deliverabilityCategory(): DeliverabilityScore {
    return this.deliverability;
  }
  set deliverabilityCategory(_category: DeliverabilityScore) {}

  get deliverabilityLevel(): DeliverabilityScore {
    return this.deliverability;
  }
  set deliverabilityLevel(_level: DeliverabilityScore) {}

  /** Smartlead calls the deliverability score the "warm up reputation". */
  get warmupReputation(): number {
    return this.deliverabilityScore;
  }
  set warmupReputation(reputation: number | string) {
    const score = EmailAccount.parseScore(reputation);
    if (score !== undefined && this.deliverabilityScore === undefined) {
      this.deliverabilityScore = score;
    }
  }

  /** Is the inbox already sending for the given campaign? */
  isAssociatedWithCampaign(campaignId: string): boolean {
    if (!campaignId) {
      return false;
    }
    return this.campaignIds.includes(String(campaignId));
  }

  /**
   * Associates the inbox with a campaign. Associating the same campaign twice
   * is a no-op so callers can safely retry.
   *
   * @returns true when the inbox changed.
   */
  associateWithCampaign(campaignId: string): boolean {
    if (!campaignId || this.isAssociatedWithCampaign(campaignId)) {
      return false;
    }
    this.campaignIds.push(String(campaignId));
    return true;
  }

  removeCampaign(campaignId: string): boolean {
    const index = this.campaignIds.indexOf(String(campaignId));
    if (index === -1) {
      return false;
    }
    this.campaignIds.splice(index, 1);
    return true;
  }

  addTag(tag: string): boolean {
    if (!tag || this.tags.includes(tag)) {
      return false;
    }
    this.tags.push(tag);
    return true;
  }

  /**
   * Hydrates the inbox with the values Smartlead owns: when the inbox was
   * created and how well it is warmed up.
   */
  hydrateFromSmartlead(smartleadEmailAccount: Record<string, any>): this {
    if (!smartleadEmailAccount) {
      return this;
    }
    const {
      smartleadInboxId,
      smartleadClientId,
      email,
      createdAt,
      deliverabilityScore,
    } = EmailAccount.parseSmartleadEmailAccount(smartleadEmailAccount);
    this.smartleadInboxId = this.smartleadInboxId
      ? this.smartleadInboxId
      : smartleadInboxId;
    this.smartleadClientId = this.smartleadClientId
      ? this.smartleadClientId
      : smartleadClientId;
    this.email = this.email ? this.email : email;
    if (createdAt !== undefined) {
      this.createdAt = createdAt;
    }
    if (deliverabilityScore !== undefined) {
      this.deliverabilityScore = deliverabilityScore;
    } else {
      delete this.deliverabilityScore;
    }
    return this;
  }

  /* ------------------------------------------------------------------ *
   * Mapping helpers
   * ------------------------------------------------------------------ */

  /** Datastore documents are sometimes wrapped inside of a `data` envelope. */
  static unwrap(item: any): Record<string, any> {
    if (!item || typeof item !== 'object') {
      return {};
    }
    if (item.data && typeof item.data === 'object' && !Array.isArray(item.data)) {
      return item.data;
    }
    return item;
  }

  static map(item: any): EmailAccount {
    return new EmailAccount(EmailAccount.unwrap(item));
  }

  static mapAll(items: any[]): EmailAccount[] {
    if (!items || !Array.isArray(items)) {
      return [];
    }
    return items
      .filter((item) => item !== null && item !== undefined)
      .map((item) => EmailAccount.map(item));
  }

  static normalizeId(id: any): string {
    if (id === null || id === undefined || id === '') {
      return undefined;
    }
    return String(id);
  }

  static normalizeList(list: any): string[] {
    if (list === null || list === undefined) {
      return [];
    }
    const values = Array.isArray(list) ? list : [list];
    return Array.from(
      new Set(
        values
          .filter((value) => value !== null && value !== undefined && value !== '')
          .map((value) => String(value)),
      ),
    );
  }

  static normalizeDate(date: any): string {
    if (date === null || date === undefined || date === '') {
      return undefined;
    }
    if (date instanceof Date) {
      return date.toISOString();
    }
    return String(date);
  }

  /**
   * Turns whatever Smartlead reports into a number. Smartlead returns the warm
   * up reputation as a percentage string, for example `"100%"`.
   */
  static parseScore(value: any): number {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    if (typeof value === 'number') {
      return Number.isFinite(value) ? value : undefined;
    }
    const parsed = parseFloat(String(value).replace('%', '').trim());
    return Number.isNaN(parsed) ? undefined : parsed;
  }

  /**
   * Maps a deliverability score onto its bucket:
   * 100 is High, 98-99 Medium, 95-97 Low, anything lower is Burned and a
   * missing score is Unknown.
   */
  static mapDeliverabilityScore(score: any): DeliverabilityScore {
    if (
      typeof score === 'string' &&
      Object.values(DeliverabilityScore).includes(score as DeliverabilityScore)
    ) {
      return score as DeliverabilityScore;
    }
    const parsedScore = EmailAccount.parseScore(score);
    if (parsedScore === undefined) {
      return DeliverabilityScore.Unknown;
    }
    if (parsedScore >= HIGH_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.High;
    }
    if (parsedScore >= MEDIUM_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.Medium;
    }
    if (parsedScore >= LOW_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.Low;
    }
    return DeliverabilityScore.Burned;
  }

  /** Reads the fields we care about out of a Smartlead email account payload. */
  static parseSmartleadEmailAccount(raw: Record<string, any>): {
    smartleadInboxId: string;
    smartleadClientId: string;
    email: string;
    createdAt: string;
    deliverabilityScore: number;
  } {
    const source = raw ? raw : {};
    return {
      smartleadInboxId: EmailAccount.normalizeId(
        source.id ?? source.email_account_id ?? source.smartleadInboxId,
      ),
      smartleadClientId: EmailAccount.normalizeId(
        source.client_id ?? source.clientId ?? source.smartleadClientId,
      ),
      email: source.from_email ?? source.email ?? source.username,
      createdAt: EmailAccount.normalizeDate(
        source.created_at ?? source.createdAt,
      ),
      deliverabilityScore: EmailAccount.parseScore(
        source?.warmup_details?.warmup_reputation ??
          source?.warmup_details?.warmupReputation ??
          source?.warmup_reputation ??
          source?.warmupReputation ??
          source?.deliverabilityScore,
      ),
    };
  }

  /** Builds an inbox out of a raw Smartlead email account payload. */
  static fromSmartleadEmailAccount(
    raw: Record<string, any>,
    overrides: EmailAccountLike = {},
  ): EmailAccount {
    const account = new EmailAccount(
      EmailAccount.parseSmartleadEmailAccount(raw),
    );
    Object.entries(overrides ? overrides : {}).forEach(([key, value]) => {
      if (value !== undefined) {
        account[key] = value;
      }
    });
    return new EmailAccount(account);
  }

  /* ------------------------------------------------------------------ *
   * Smartlead lookups
   * ------------------------------------------------------------------ */

  /**
   * Fetches an inbox from Smartlead, either by its inbox id or, when we only
   * know the address, by scanning the list of every inbox.
   *
   * @returns the raw Smartlead payload or undefined when Smartlead does not
   * know about the inbox.
   */
  static async fetchFromSmartlead({
    smartleadInboxId,
    email,
    apiKey =<REDACTED>
  }: {
    smartleadInboxId?: string;
    email?: string;
    apiKey?: string;
  }): Promise<Record<string, any>> {
    const urls: string[] = [];
    if (smartleadInboxId) {
      urls.push(
        `${SMARTLEAD_API_BASE_URL}/email-accounts/${smartleadInboxId}?api_key=${apiKey}`,
      );
    }
    urls.push(
      `${SMARTLEAD_API_BASE_URL}/email-accounts/?api_key=${apiKey}&offset=0&limit=1000`,
    );
    for (const url of urls) {
      try {
        const res: any = await fetch(url);
        if (!res || res.status === 404) {
          continue;
        }
        let body: any;
        try {
          body = await res.json();
        } catch (error) {
          EmailAccount.logger.error(
            `Failed to parse the Smartlead email account response: ${error}`,
          );
          continue;
        }
        const match = EmailAccount.findInSmartleadResponse(body, {
          smartleadInboxId,
          email,
        });
        if (match) {
          return match;
        }
      } catch (error) {
        EmailAccount.logger.error(
          `Failed to load the email account from Smartlead: ${error}`,
        );
      }
    }
    return undefined;
  }

  /** Lists every inbox Smartlead knows about, optionally for a single client. */
  static async listSmartleadEmailAccounts({
    smartleadClientId,
    apiKey =<REDACTED>
    limit = 1000,
    offset = 0,
  }: {
    smartleadClientId?: string;
    apiKey?: string;
    limit?: number;
    offset?: number;
  } = {}): Promise<Record<string, any>[]> {
    const res: any = await fetch(
      `${SMARTLEAD_API_BASE_URL}/email-accounts/?api_key=${apiKey}&offset=${offset}&limit=${limit}`,
    );
    if (!res || res.status === 404) {
      return [];
    }
    const body = await res.json();
    const accounts = EmailAccount.toSmartleadCandidates(body);
    if (!smartleadClientId) {
      return accounts;
    }
    return accounts.filter(
      (account) =>
        EmailAccount.normalizeId(account?.client_id) ===
        EmailAccount.normalizeId(smartleadClientId),
    );
  }

  private static toSmartleadCandidates(body: any): Record<string, any>[] {
    if (!body) {
      return [];
    }
    if (Array.isArray(body)) {
      return body;
    }
    if (Array.isArray(body.data)) {
      return body.data;
    }
    if (Array.isArray(body.email_accounts)) {
      return body.email_accounts;
    }
    if (typeof body === 'object') {
      return [body];
    }
    return [];
  }

  private static findInSmartleadResponse(
    body: any,
    {
      smartleadInboxId,
      email,
    }: { smartleadInboxId?: string; email?: string } = {},
  ): Record<string, any> {
    const candidates = EmailAccount.toSmartleadCandidates(body);
    for (const candidate of candidates) {
      if (!candidate || typeof candidate !== 'object') {
        continue;
      }
      const candidateId = EmailAccount.normalizeId(
        candidate.id ?? candidate.email_account_id,
      );
      const candidateEmail = candidate.from_email ?? candidate.email;
      if (
        smartleadInboxId &&
        candidateId &&
        candidateId === EmailAccount.normalizeId(smartleadInboxId)
      ) {
        return candidate;
      }
      if (
        email &&
        candidateEmail &&
        String(candidateEmail).toLowerCase() === String(email).toLowerCase()
      ) {
        return candidate;
      }
      // A single document without an identifier is the inbox we asked for.
      if (
        candidates.length === 1 &&
        !candidateId &&
        !candidateEmail &&
        (candidate.created_at ||
          candidate.createdAt ||
          candidate.warmup_details ||
          candidate.warmup_reputation)
      ) {
        return candidate;
      }
    }
    return undefined;
  }

  /* ------------------------------------------------------------------ *
   * Selecting inboxes for a campaign
   * ------------------------------------------------------------------ */

  /**
   * How many inboxes a campaign needs:
   * total emails / days in the campaign / emails per inbox per day.
   */
  static requiredNumberOfInboxes({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const days = numberOfDaysInCampaign
      ? numberOfDaysInCampaign
      : DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const emailsPerInboxPerDay = numberOfEmailsPerInboxPerDay
      ? numberOfEmailsPerInboxPerDay
      : DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    const total = Number(totalNumberOfEmailsToSend);
    if (!total || Number.isNaN(total) || total <= 0) {
      return 0;
    }
    const required = Math.floor(total / days / emailsPerInboxPerDay);
    return required > 0 ? required : 0;
  }

  /** How many other inboxes in the pool share this inbox' sending domain. */
  static numberOfOtherInboxesOnDomain(
    account: EmailAccount,
    pool: EmailAccount[],
  ): number {
    const domain = account?.domain;
    if (!domain) {
      return 0;
    }
    return pool.filter(
      (candidate) =>
        candidate !== account &&
        candidate?.domain === domain &&
        candidate?.smartleadInboxId !== account?.smartleadInboxId,
    ).length;
  }

  /**
   * Ranks inboxes so the best sender comes first:
   * 1. the highest deliverability score
   * 2. the fewest campaigns already associated
   * 3. the fewest other inboxes on the same domain
   * 4. the oldest inbox
   */
  static rank(accounts: EmailAccount[]): EmailAccount[] {
    const pool = EmailAccount.mapAll(accounts);
    const domainCounts = new Map<EmailAccount, number>();
    pool.forEach((account) =>
      domainCounts.set(
        account,
        EmailAccount.numberOfOtherInboxesOnDomain(account, pool),
      ),
    );
    return pool.sort((a, b) => {
      const scoreDifference =
        EmailAccount.scoreForSorting(b) - EmailAccount.scoreForSorting(a);
      if (scoreDifference !== 0) {
        return scoreDifference;
      }
      const campaignDifference =
        a.numberOfCampaignAssociated - b.numberOfCampaignAssociated;
      if (campaignDifference !== 0) {
        return campaignDifference;
      }
      const domainDifference = domainCounts.get(a) - domainCounts.get(b);
      if (domainDifference !== 0) {
        return domainDifference;
      }
      const createdAtDifference =
        EmailAccount.createdAtForSorting(a) -
        EmailAccount.createdAtForSorting(b);
      if (createdAtDifference !== 0) {
        return createdAtDifference;
      }
      return String(a.smartleadInboxId).localeCompare(
        String(b.smartleadInboxId),
      );
    });
  }

  private static scoreForSorting(account: EmailAccount): number {
    const score = EmailAccount.parseScore(account?.deliverabilityScore);
    return score === undefined ? -1 : score;
  }

  private static createdAtForSorting(account: EmailAccount): number {
    if (!account?.createdAt) {
      // Inboxes without a creation time are treated as the newest ones.
      return Number.MAX_SAFE_INTEGER;
    }
    const time = new Date(account.createdAt).getTime();
    return Number.isNaN(time) ? Number.MAX_SAFE_INTEGER : time;
  }

  /**
   * Picks the best inboxes for a campaign out of the given pool.
   */
  static selectForCampaign(
    accounts: EmailAccount[],
    {
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    }: {
      totalNumberOfEmailsToSend: number;
      numberOfDaysInCampaign?: number;
      numberOfEmailsPerInboxPerDay?: number;
    },
  ): EmailAccount[] {
    const required = EmailAccount.requiredNumberOfInboxes({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    return EmailAccount.rank(accounts).slice(0, required);
  }
}

/** The email account is the aggregate of the email infrastructure. */
export { EmailAccount as EmailInboxAccount };

import { Injectable, Logger, NotFoundException, Optional } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import { EmailAccount, EmailAccountLike } from './emailAccount.entity';

export const DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE = 100;

export type EmailAccountPagination = {
  page?: number;
  pageSize?: number;
};

/**
 * The email infrastructure repository: every read and write of an email
 * account goes through here so the rest of the code base never has to know
 * about the shape of the underlying datastore.
 */
@Injectable()
export class EmailInfraEntity {
  private readonly logger = new Logger(EmailInfraEntity.name);
  private static fallbackDatastoreService: DatastoreService;

  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
  ) {}

  /**
   * The datastore is optional so the entity can be used from the delivery ops
   * scripts and from tests that do not wire up the datastore module.
   */
  private get datastore(): DatastoreService {
    if (this.datastoreService) {
      return this.datastoreService;
    }
    if (!EmailInfraEntity.fallbackDatastoreService) {
      EmailInfraEntity.fallbackDatastoreService = new DatastoreService();
    }
    return EmailInfraEntity.fallbackDatastoreService;
  }

  /** Creates or updates an inbox. Keyed on the Smartlead inbox id. */
  async save(emailAccount: EmailAccountLike): Promise<EmailAccount> {
    const account = new EmailAccount(emailAccount);
    account.updatedAt = new Date().toISOString();
    this.logger.log(
      `Saving email account ${account.email} (${account.smartleadInboxId})`,
    );
    await this.datastore.store(
      new StoreDataDto({
        data: account,
        context: {
          uniqueId: account.smartleadInboxId,
          documentType: documentType.EMAIL_ACCOUNT,
        },
      }),
    );
    return account;
  }

  /** Looks an inbox up by its Smartlead inbox id, or undefined when unknown. */
  async findBySmartleadInboxId(
    smartleadInboxId: string,
  ): Promise<EmailAccount> {
    const [account] = await this.findByField(
      'data.smartleadInboxId',
      EmailAccount.normalizeId(smartleadInboxId),
    );
    return account;
  }

  /** Looks an inbox up by the address we send from. */
  async findByEmail(email: string): Promise<EmailAccount> {
    const [account] = await this.findByField('data.email', email);
    return account;
  }

  /** Every inbox that belongs to a Smartlead client. */
  async findBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    return this.findByField(
      'data.smartleadClientId',
      EmailAccount.normalizeId(smartleadClientId),
    );
  }

  /** Every inbox that is currently sending for a campaign. */
  async findByCampaignId(campaignId: string): Promise<EmailAccount[]> {
    return this.findByField('data.campaignIds', String(campaignId));
  }

  /** A page of inboxes. Without pagination every inbox is returned. */
  async findAll(pagination?: EmailAccountPagination): Promise<EmailAccount[]> {
    return this.findByField(
      'data.smartleadInboxId',
      { $exists: true },
      pagination,
    );
  }

  /** Deletes an inbox. */
  async delete(smartleadInboxId: string): Promise<{ message: string }> {
    this.logger.log(`Deleting email account ${smartleadInboxId}`);
    await this.datastore.remove({
      id: EmailAccount.normalizeId(smartleadInboxId),
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return { message: 'Email account deleted successfully' };
  }

  /**
   * Associates every inbox with the campaign. Inboxes that are already
   * associated are left untouched, which keeps the operation idempotent.
   *
   * @throws NotFoundException when any of the inboxes is unknown.
   */
  async associateWithCampaign({
    emailAccountIds,
    campaignId,
  }: {
    emailAccountIds: string[];
    campaignId: string;
  }): Promise<EmailAccount[]> {
    const ids = EmailAccount.normalizeList(emailAccountIds);
    const accounts = await Promise.all(
      ids.map(async (id) => ({
        id,
        account: await this.findBySmartleadInboxId(id),
      })),
    );
    const missingIds = accounts
      .filter(({ account }) => !account)
      .map(({ id }) => id);
    if (missingIds.length > 0) {
      this.logger.error(
        `Email accounts not found: ${missingIds.join(', ')}. Not associating them with campaign ${campaignId}`,
      );
      throw new NotFoundException(
        `Email accounts not found: ${missingIds.join(', ')}`,
      );
    }
    return Promise.all(
      accounts.map(async ({ account }) => {
        if (!account.associateWithCampaign(campaignId)) {
          this.logger.log(
            `Email account ${account.smartleadInboxId} is already associated with campaign ${campaignId}`,
          );
          return account;
        }
        return this.save(account);
      }),
    );
  }

  private async findByField(
    fieldKey: string,
    fieldValue: string | Record<string, any>,
    pagination?: EmailAccountPagination,
  ): Promise<EmailAccount[]> {
    if (fieldValue === undefined || fieldValue === null) {
      return [];
    }
    const res = await this.datastore.getByField({
      fieldKey,
      fieldValue,
      documentType: documentType.EMAIL_ACCOUNT,
      ...(pagination
        ? {
            pagination: {
              page: pagination.page ? pagination.page : 0,
              pageSize: pagination.pageSize
                ? pagination.pageSize
                : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
            },
          }
        : {}),
    });
    return EmailAccount.mapAll(res?.data);
  }
}

