/**
 * The email account aggregate lives in `emailAccount.entity.ts`, this barrel
 * mirrors the naming used by the other domain entities.
 */
export * from './emailAccount.entity';

import {
  IsArray,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';

export class EmailAccountDto {
  @IsString()
  email: string;
  @IsString()
  smartleadClientId: string;
  /** The id of the inbox inside of Smartlead. Optional when the email is known. */
  @IsOptional()
  @IsString()
  smartleadInboxId?: string;
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  tags?: string[];
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  campaignIds?: string[];
}

export class EmailAccountListDto {
  @IsNumber()
  totalNumberOfEmailsToSend: number;
  @IsString()
  smartleadClientId: string;
  @IsString()
  campaignId: string;
  @IsOptional()
  @IsNumber()
  numberOfDaysInCampaign?: number;
  @IsOptional()
  @IsNumber()
  numberOfEmailsPerInboxPerDay?: number;
}

export class AssociateEmailAccountsWithCampaignDto {
  @IsArray()
  @IsString({ each: true })
  emailAccountIds: string[];
  @IsString()
  campaignId: string;
}

export class EmailAccountPaginationDto {
  @IsOptional()
  @IsNumber()
  @Min(0)
  page?: number;
  @IsOptional()
  @IsNumber()
  @Min(1)
  pageSize?: number;
}

export {
  DeliverabilityScore,
  DeliverabilityRating,
  Deliverability,
  DeliverabilityStatus,
  DeliverabilityCategory,
  DeliverabilityLevel,
  EmailAccountDeliverability,
  EmailAccount,
} from '../entities/emailAccount.entity';

import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';
import { DatastoreService } from '../datastore/datastore.service';
import {
  EmailAccountPagination,
  EmailInfraEntity,
} from './entities/emailinfra.entity';
import {
  DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
  DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  EmailAccount,
} from './entities/emailAccount.entity';

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private lazyEmailInfraEntity: EmailInfraEntity;

  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
    @Optional() private readonly emailInfraEntity?: EmailInfraEntity,
  ) {}

  /**
   * The repository is optional so the service stays usable from the delivery
   * ops scripts, where only a datastore is available.
   */
  private get emailAccounts(): EmailInfraEntity {
    if (this.emailInfraEntity) {
      return this.emailInfraEntity;
    }
    if (!this.lazyEmailInfraEntity) {
      this.lazyEmailInfraEntity = new EmailInfraEntity(this.datastoreService);
    }
    return this.lazyEmailInfraEntity;
  }

  /**
   * Returns the inboxes a campaign should send from.
   *
   * The size of the pool is the total number of emails divided by the number of
   * days in the campaign divided by how many emails a single inbox sends per
   * day. The pool is filled with the client's healthiest inboxes: the highest
   * deliverability score first, then the inboxes that are associated with the
   * fewest campaigns, then the inboxes with the fewest siblings on the same
   * sending domain and finally the oldest inboxes.
   *
   * Example: 500 emails over 10 days at 20 emails per inbox per day needs 2
   * inboxes.
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    const numberOfInboxes = EmailAccount.requiredNumberOfInboxes({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Campaign ${campaignId} needs ${numberOfInboxes} inboxes to send ${totalNumberOfEmailsToSend} emails over ${numberOfDaysInCampaign} days for client ${smartleadClientId}`,
    );
    const availableEmailAccounts =
      await this.emailAccounts.findBySmartleadClientId(smartleadClientId);
    const bestEmailAccounts = EmailAccount.rank(availableEmailAccounts).slice(
      0,
      numberOfInboxes,
    );
    this.logger.log(
      `Selected ${bestEmailAccounts.length} of ${availableEmailAccounts.length} inboxes for campaign ${campaignId}`,
    );
    return bestEmailAccounts;
  }

  /**
   * Associates inboxes with a campaign. Associating an inbox that is already
   * sending for the campaign is a no-op, so the call can safely be retried.
   *
   * @throws NotFoundException when any of the requested inboxes is unknown.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsWithCampaignDto): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    this.logger.log(
      `Associating email accounts ${EmailAccount.normalizeList(emailAccountIds).join(', ')} with campaign ${campaignId}`,
    );
    return this.emailAccounts.associateWithCampaign({
      emailAccountIds,
      campaignId,
    });
  }

  /**
   * Creates or updates an inbox. The creation time and the warm up reputation
   * are always hydrated from Smartlead, which owns them.
   *
   * @throws NotFoundException when Smartlead does not know the inbox.
   */
  async saveEmailAccount(
    emailAccount: EmailAccountDto & { smartleadInboxId?: string },
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailAccount.normalizeId(
      emailAccount?.smartleadInboxId ?? (emailAccount as any)?.id,
    );
    const email = emailAccount?.email;
    if (!smartleadInboxId && !email) {
      throw new BadRequestException(
        'Either a smartleadInboxId or an email is required to save an email account',
      );
    }
    const smartleadEmailAccount = await EmailAccount.fetchFromSmartlead({
      smartleadInboxId,
      email,
    });
    if (!smartleadEmailAccount) {
      this.logger.error(
        `Email account ${smartleadInboxId ? smartleadInboxId : email} not found in Smartlead`,
      );
      throw new NotFoundException('Email account not found in Smartlead');
    }
    const existingEmailAccount = smartleadInboxId
      ? await this.emailAccounts.findBySmartleadInboxId(smartleadInboxId)
      : await this.emailAccounts.findByEmail(email);
    const account = new EmailAccount({
      ...(existingEmailAccount ? existingEmailAccount : {}),
      ...EmailAccount.normalizeInput(emailAccount),
      ...(smartleadInboxId ? { smartleadInboxId } : {}),
    });
    account.hydrateFromSmartlead(smartleadEmailAccount);
    return this.emailAccounts.save(account);
  }

  /** Looks an inbox up by its Smartlead inbox id. */
  async getEmailAccount(
    emailAccount: (EmailAccountDto & { smartleadInboxId?: string }) | string,
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailAccount.normalizeId(
      typeof emailAccount === 'string'
        ? emailAccount
        : (emailAccount?.smartleadInboxId ?? (emailAccount as any)?.id),
    );
    if (!smartleadInboxId) {
      // Fall back to the email address when only the inbox address is known.
      const email =
        typeof emailAccount === 'string' ? emailAccount : emailAccount?.email;
      if (!email) {
        throw new BadRequestException('A smartleadInboxId is required');
      }
      return this.getEmailAccountByEmail(email);
    }
    const account =
      await this.emailAccounts.findBySmartleadInboxId(smartleadInboxId);
    if (!account) {
      throw new NotFoundException(
        `Email account ${smartleadInboxId} not found`,
      );
    }
    return account;
  }

  /** Looks an inbox up by its Smartlead inbox id. */
  async getEmailAccountById(smartleadInboxId: string): Promise<EmailAccount> {
    return this.getEmailAccount(smartleadInboxId);
  }

  /** A page of inboxes. Without pagination every inbox is returned. */
  async getAllEmailAccounts(
    pagination?: EmailAccountPagination,
  ): Promise<EmailAccount[]> {
    const hasPagination =
      pagination &&
      (pagination.page !== undefined || pagination.pageSize !== undefined);
    return this.emailAccounts.findAll(hasPagination ? pagination : undefined);
  }

  /** Looks an inbox up by the address it sends from. */
  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    const account = await this.emailAccounts.findByEmail(email);
    if (!account) {
      throw new NotFoundException(`Email account ${email} not found`);
    }
    return account;
  }

  /** Every inbox that belongs to a Smartlead client. */
  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    return this.emailAccounts.findBySmartleadClientId(smartleadClientId);
  }

  /** Every inbox that belongs to a Smartlead client. */
  async getEmailAccountsBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    return this.getEmailAccountBySmartleadClientId(smartleadClientId);
  }

  /** Every inbox that is currently sending for a campaign. */
  async getEmailAccountsByCampaignId(
    campaignId: string,
  ): Promise<EmailAccount[]> {
    return this.emailAccounts.findByCampaignId(campaignId);
  }

  /** Deletes an inbox. */
  async deleteEmailAccount(
    emailAccount: (EmailAccountDto & { smartleadInboxId?: string }) | string,
  ): Promise<{ message: string }> {
    const account = await this.getEmailAccount(emailAccount);
    return this.emailAccounts.delete(account.smartleadInboxId);
  }

  /**
   * Imports every inbox Smartlead has provisioned for a client.
   * Used by the delivery ops import script.
   */
  async importEmailAccountsFromSmartlead({
    smartleadClientId,
    tags = [],
  }: {
    smartleadClientId: string;
    tags?: string[];
  }): Promise<EmailAccount[]> {
    const smartleadEmailAccounts = await EmailAccount.listSmartleadEmailAccounts(
      { smartleadClientId },
    );
    this.logger.log(
      `Importing ${smartleadEmailAccounts.length} inboxes for client ${smartleadClientId}`,
    );
    const importedEmailAccounts: EmailAccount[] = [];
    for (const smartleadEmailAccount of smartleadEmailAccounts) {
      const account = EmailAccount.fromSmartleadEmailAccount(
        smartleadEmailAccount,
        { smartleadClientId, tags },
      );
      const existingEmailAccount =
        await this.emailAccounts.findBySmartleadInboxId(
          account.smartleadInboxId,
        );
      importedEmailAccounts.push(
        await this.emailAccounts.save(
          new EmailAccount({
            ...(existingEmailAccount ? existingEmailAccount : {}),
            ...account,
            tags: [...(existingEmailAccount?.tags ?? []), ...account.tags],
            campaignIds: existingEmailAccount?.campaignIds ?? [],
          }),
        ),
      );
    }
    return importedEmailAccounts;
  }

  /**
   * Refreshes the warm up reputation of the stored inboxes from Smartlead.
   * Used by the delivery ops reputation sync script.
   */
  async syncEmailAccountReputation(
    smartleadInboxId?: string,
  ): Promise<EmailAccount[]> {
    const accounts = smartleadInboxId
      ? [await this.getEmailAccount(smartleadInboxId)]
      : await this.getAllEmailAccounts();
    const syncedAccounts: EmailAccount[] = [];
    for (const account of accounts) {
      const smartleadEmailAccount = await EmailAccount.fetchFromSmartlead({
        smartleadInboxId: account.smartleadInboxId,
        email: account.email,
      });
      if (!smartleadEmailAccount) {
        this.logger.warn(
          `Email account ${account.smartleadInboxId} no longer exists in Smartlead, skipping`,
        );
        continue;
      }
      delete account.deliverabilityScore;
      account.hydrateFromSmartlead(smartleadEmailAccount);
      syncedAccounts.push(await this.emailAccounts.save(account));
    }
    return syncedAccounts;
  }
}

