/**
 * Drops the keys that are not set so partial input never overwrites a value
 * we already know about.
 */
static omitUndefined(item: any): Record<string, any> {
  return Object.entries(EmailAccount.unwrap(item)).reduce(
    (accumulator, [key, value]) => {
      if (value !== undefined) {
        accumulator[key] = value;
      }
      return accumulator;
    },
    {} as Record<string, any>,
  );
}

