import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
} from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';
import { EmailAccount } from './entities/emailAccount.entity';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  /** Creates or updates a sending inbox. */
  @Post('email-accounts')
  async saveEmailAccount(
    @Body() emailAccountDto: EmailAccountDto,
  ): Promise<EmailAccount> {
    return this.emailinfraService.saveEmailAccount(emailAccountDto);
  }

  /** Lists the sending inboxes. */
  @Get('email-accounts')
  async getAllEmailAccounts(
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ): Promise<EmailAccount[]> {
    return this.emailinfraService.getAllEmailAccounts({
      page: page === undefined ? undefined : parseInt(page, 10),
      pageSize: pageSize === undefined ? undefined : parseInt(pageSize, 10),
    });
  }

  /** The best inboxes to send a campaign from. */
  @Post('email-accounts/best')
  async getBestEmailAccountsForCampaign(
    @Body() emailAccountListDto: EmailAccountListDto,
  ): Promise<EmailAccount[]> {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountListDto,
    );
  }

  /** Associates inboxes with a campaign. */
  @Post('email-accounts/campaign')
  async associateEmailAccountsWithCampaign(
    @Body()
    associateEmailAccountsWithCampaignDto: AssociateEmailAccountsWithCampaignDto,
  ): Promise<EmailAccount[]> {
    return this.emailinfraService.associateEmailAccountsWithCampaign(
      associateEmailAccountsWithCampaignDto,
    );
  }

  @Get('email-accounts/email/:email')
  async getEmailAccountByEmail(
    @Param('email') email: string,
  ): Promise<EmailAccount> {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @Get('email-accounts/client/:smartleadClientId')
  async getEmailAccountBySmartleadClientId(
    @Param('smartleadClientId') smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
      smartleadClientId,
    );
  }

  @Get('email-accounts/:smartleadInboxId')
  async getEmailAccount(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ): Promise<EmailAccount> {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  @Delete('email-accounts/:smartleadInboxId')
  async deleteEmailAccount(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ): Promise<{ message: string }> {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }
}

import { Module } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraController } from './emailinfra.controller';
import { DatastoreModule } from '../datastore/datastore.module';
import { EmailInfraEntity } from './entities/emailinfra.entity';

@Module({
  controllers: [EmailinfraController],
  providers: [EmailinfraService, EmailInfraEntity],
  imports: [DatastoreModule],
  exports: [EmailinfraService],
})
export class EmailinfraModule {}

import { Logger } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { EmailinfraModule } from '../emailinfra.module';
import { EmailinfraService } from '../emailinfra.service';
import { EmailAccount } from '../entities/emailAccount.entity';

const logger = new Logger('importEmailAccounts');

/**
 * Imports every warmed inbox Smartlead has provisioned for a client into the
 * email account datastore.
 *
 * Usage:
 *   DATASTORE=mongo SMARTLEAD_REPORT_API_KEY=... \
 *     node dist/emailinfra/scripts/importEmailAccounts.js <smartleadClientId> [tag,tag]
 */
export async function importEmailAccounts(
  smartleadClientId: string,
  tags: string[] = [],
): Promise<EmailAccount[]> {
  if (!smartleadClientId) {
    throw new Error('A smartleadClientId is required');
  }
  if (!process.env.DATASTORE) {
    throw new Error('DATASTORE has to be configured to import email accounts');
  }
  const app = await NestFactory.createApplicationContext(EmailinfraModule);
  try {
    const emailinfraService = app.get(EmailinfraService);
    const emailAccounts =
      await emailinfraService.importEmailAccountsFromSmartlead({
        smartleadClientId,
        tags,
      });
    emailAccounts.forEach((emailAccount) =>
      logger.log(
        `Imported ${emailAccount.email} (${emailAccount.smartleadInboxId}) deliverability: ${emailAccount.deliverability}`,
      ),
    );
    logger.log(
      `Imported ${emailAccounts.length} inboxes for client ${smartleadClientId}`,
    );
    return emailAccounts;
  } finally {
    await app.close();
  }
}

if (require.main === module) {
  const [smartleadClientId, tags] = process.argv.slice(2);
  importEmailAccounts(
    smartleadClientId,
    tags ? tags.split(',').filter(Boolean) : [],
  )
    .then(() => process.exit(0))
    .catch((error) => {
      logger.error(`Failed to import the email accounts: ${error}`);
      process.exit(1);
    });
}

import { Logger } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { EmailinfraModule } from '../emailinfra.module';
import { EmailinfraService } from '../emailinfra.service';
import { EmailAccount } from '../entities/emailAccount.entity';

const logger = new Logger('syncEmailAccountReputation');

/**
 * Refreshes the warm up reputation of the stored inboxes from Smartlead so the
 * deliverability of every inbox stays up to date.
 *
 * Usage:
 *   DATASTORE=mongo SMARTLEAD_REPORT_API_KEY=... \
 *     node dist/emailinfra/scripts/syncEmailAccountReputation.js [smartleadInboxId]
 */
export async function syncEmailAccountReputation(
  smartleadInboxId?: string,
): Promise<EmailAccount[]> {
  if (!process.env.DATASTORE) {
    throw new Error(
      'DATASTORE has to be configured to sync the email account reputation',
    );
  }
  const app = await NestFactory.createApplicationContext(EmailinfraModule);
  try {
    const emailinfraService = app.get(EmailinfraService);
    const emailAccounts =
      await emailinfraService.syncEmailAccountReputation(smartleadInboxId);
    emailAccounts.forEach((emailAccount) =>
      logger.log(
        `${emailAccount.email} (${emailAccount.smartleadInboxId}) score: ${emailAccount.deliverabilityScore} deliverability: ${emailAccount.deliverability}`,
      ),
    );
    logger.log(`Synced ${emailAccounts.length} inboxes`);
    return emailAccounts;
  } finally {
    await app.close();
  }
}

if (require.main === module) {
  const [smartleadInboxId] = process.argv.slice(2);
  syncEmailAccountReputation(smartleadInboxId)
    .then(() => process.exit(0))
    .catch((error) => {
      logger.error(`Failed to sync the email account reputation: ${error}`);
      process.exit(1);
    });
}

