  /**
   * Assigns the sending inboxes picked by the email infrastructure service to
   * the Smartlead campaign.
   */
  async assignSendingInboxesToSmartlead(smartleadInboxIds: string[] = []) {
    if (!smartleadInboxIds || smartleadInboxIds.length === 0) {
      this.logger.warn(
        `No sending inboxes to assign to campaign: ${this.campaignData?.id}`,
      );
      return;
    }
    /*
    curl https://server.smartlead.ai/api/v1/campaigns/{campaign_id}/email-accounts?api_key={API_KEY}
    --data '{"email_account_ids": [1,2,3]}'
    */
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    this.logger.log(
      `Assigning inboxes ${smartleadInboxIds.join(', ')} to campaign: ${this.campaignData?.id}`,
    );
    const res = await fetch(
      `https://server.smartlead.ai/api/v1/campaigns/${this.campaignData?.id}/email-accounts?api_key=${apiKey}`,
      {
        method: 'POST',
        body: JSON.stringify({
          email_account_ids: smartleadInboxIds.map((id) =>
            parseInt(`${id}`, 10),
          ),
        }),
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );
    if (!res.ok) {
      this.logger.error(
        `Failed to assign the sending inboxes to campaign ${this.campaignData?.id}: ${res.status}`,
      );
      throw new Error('Failed to assign the sending inboxes to the campaign');
    }
    return await res.json();
  }
}

