import {
  DeliverabilityScore,
  EmailAccount,
} from './emailAccount.entity';

describe('EmailAccount', () => {
  it('is keyed by the smartlead inbox id and derives the sending domain', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: '101',
      smartleadClientId: '22',
      email: 'ada@sending.trychamp.co',
      tags: ['warmed'],
    });

    expect(emailAccount.smartleadInboxId).toBe('101');
    expect(emailAccount.id).toBe('101');
    expect(emailAccount.smartleadClientId).toBe('22');
    expect(emailAccount.email).toBe('ada@sending.trychamp.co');
    expect(emailAccount.domain).toBe('sending.trychamp.co');
    expect(emailAccount.tags).toEqual(['warmed']);
    expect(emailAccount.campaignIds).toEqual([]);
    expect(emailAccount.numberOfCampaignAssociated).toBe(0);
  });

  it('exposes the number of campaigns it is associated with', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: '101',
      campaignIds: ['campaign-1'],
    });

    expect(emailAccount.numberOfCampaignAssociated).toBe(1);
    expect(emailAccount.associateWithCampaign('campaign-2')).toBe(true);
    expect(emailAccount.numberOfCampaignAssociated).toBe(2);
    // Associating the same campaign twice does not change the inbox.
    expect(emailAccount.associateWithCampaign('campaign-2')).toBe(false);
    expect(emailAccount.campaignIds).toEqual(['campaign-1', 'campaign-2']);
    expect(emailAccount.numberOfCampaignAssociated).toBe(2);
  });

  it.each([
    [100, DeliverabilityScore.High],
    [99, DeliverabilityScore.Medium],
    [98, DeliverabilityScore.Medium],
    [97, DeliverabilityScore.Low],
    [95, DeliverabilityScore.Low],
    [94, DeliverabilityScore.Burned],
    [0, DeliverabilityScore.Burned],
  ])('maps the deliverability score %s to %s', (score, expected) => {
    expect(EmailAccount.mapDeliverabilityScore(score)).toBe(expected);
    expect(new EmailAccount({ deliverabilityScore: score }).deliverability).toBe(
      expected,
    );
  });

  it('maps a missing deliverability score to unknown', () => {
    expect(EmailAccount.mapDeliverabilityScore(undefined)).toBe(
      DeliverabilityScore.Unknown,
    );
    expect(new EmailAccount({ smartleadInboxId: '1' }).deliverability).toBe(
      DeliverabilityScore.Unknown,
    );
  });

  it('reads the creation time and the warm up reputation out of smartlead', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: '101',
    }).hydrateFromSmartlead({
      id: 101,
      from_email: 'ada@sending.trychamp.co',
      client_id: 22,
      created_at: '2024-01-01T00:00:00.000Z',
      warmup_details: { warmup_reputation: '99%' },
    });

    expect(emailAccount.createdAt).toBe('2024-01-01T00:00:00.000Z');
    expect(emailAccount.deliverabilityScore).toBe(99);
    expect(emailAccount.deliverability).toBe(DeliverabilityScore.Medium);
    expect(emailAccount.email).toBe('ada@sending.trychamp.co');
    expect(emailAccount.smartleadClientId).toBe('22');
  });

  describe('requiredNumberOfInboxes', () => {
    it('divides the emails by the days and the emails per inbox per day', () => {
      expect(
        EmailAccount.requiredNumberOfInboxes({
          totalNumberOfEmailsToSend: 600,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(3);
    });

    it('rounds the number of inboxes down', () => {
      expect(
        EmailAccount.requiredNumberOfInboxes({
          totalNumberOfEmailsToSend: 500,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(2);
    });

    it('defaults to 10 days at 20 emails per inbox per day', () => {
      expect(
        EmailAccount.requiredNumberOfInboxes({
          totalNumberOfEmailsToSend: 600,
        }),
      ).toBe(3);
    });
  });

  describe('rank', () => {
    const buildEmailAccount = (partial) =>
      new EmailAccount({
        smartleadClientId: '22',
        createdAt: '2024-01-01T00:00:00.000Z',
        ...partial,
      });

    it('prefers the highest deliverability score', () => {
      const ranked = EmailAccount.rank([
        buildEmailAccount({
          smartleadInboxId: '1',
          email: 'a@one.com',
          deliverabilityScore: 96,
        }),
        buildEmailAccount({
          smartleadInboxId: '2',
          email: 'b@two.com',
          deliverabilityScore: 100,
        }),
        buildEmailAccount({
          smartleadInboxId: '3',
          email: 'c@three.com',
        }),
      ]);

      expect(ranked.map((account) => account.smartleadInboxId)).toEqual([
        '2',
        '1',
        '3',
      ]);
    });

    it('prefers the inbox with the fewest campaigns', () => {
      const ranked = EmailAccount.rank([
        buildEmailAccount({
          smartleadInboxId: '1',
          email: 'a@one.com',
          deliverabilityScore: 100,
          campaignIds: ['campaign-1', 'campaign-2'],
        }),
        buildEmailAccount({
          smartleadInboxId: '2',
          email: 'b@two.com',
          deliverabilityScore: 100,
          campaignIds: ['campaign-1'],
        }),
      ]);

      expect(ranked.map((account) => account.smartleadInboxId)).toEqual([
        '2',
        '1',
      ]);
    });

    it('prefers the inbox with the fewest siblings on the same domain', () => {
      const ranked = EmailAccount.rank([
        buildEmailAccount({
          smartleadInboxId: '1',
          email: 'a@crowded.com',
          deliverabilityScore: 100,
        }),
        buildEmailAccount({
          smartleadInboxId: '2',
          email: 'b@crowded.com',
          deliverabilityScore: 100,
        }),
        buildEmailAccount({
          smartleadInboxId: '3',
          email: 'c@quiet.com',
          deliverabilityScore: 100,
        }),
      ]);

      expect(ranked[0].smartleadInboxId).toBe('3');
    });

    it('prefers the oldest inbox', () => {
      const ranked = EmailAccount.rank([
        buildEmailAccount({
          smartleadInboxId: '1',
          email: 'a@one.com',
          deliverabilityScore: 100,
          createdAt: '2024-06-01T00:00:00.000Z',
        }),
        buildEmailAccount({
          smartleadInboxId: '2',
          email: 'b@two.com',
          deliverabilityScore: 100,
          createdAt: '2023-01-01T00:00:00.000Z',
        }),
      ]);

      expect(ranked.map((account) => account.smartleadInboxId)).toEqual([
        '2',
        '1',
      ]);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraModule } from './emailinfra.module';
import { DatastoreService } from '../datastore/datastore.service';
import { documentType } from '../datastore/entites/documentType';
import { DeliverabilityScore } from './entities/emailAccount.entity';

/**
 * An in memory stand in for the email account collection.
 */
const buildDatastore = () => {
  const documents = new Map<string, any>();
  const read = (document: any, fieldKey: string) =>
    fieldKey
      .replace(/^data\./, '')
      .split('.')
      .reduce((value, key) => (value ? value[key] : undefined), document);
  return {
    documents,
    store: jest.fn(async ({ data, context }) => {
      documents.set(context.uniqueId, JSON.parse(JSON.stringify(data)));
      return { message: 'Data stored successfully' };
    }),
    remove: jest.fn(async ({ id }) => {
      documents.delete(id);
      return { message: 'Data removed successfully' };
    }),
    getByField: jest.fn(async ({ fieldKey, fieldValue, pagination }) => {
      const matches = [...documents.values()].filter((document) => {
        const value = read(document, fieldKey);
        if (fieldValue && fieldValue.$exists !== undefined) {
          return (value !== undefined) === fieldValue.$exists;
        }
        return Array.isArray(value)
          ? value.includes(fieldValue)
          : value === fieldValue;
      });
      const data = pagination
        ? matches.slice(
            pagination.page * pagination.pageSize,
            pagination.page * pagination.pageSize + pagination.pageSize,
          )
        : matches;
      return { data, message: 'Data found successfully' };
    }),
  };
};

const smartleadEmailAccount = ({
  id,
  email,
  clientId = '22',
  createdAt = '2024-01-01T00:00:00.000Z',
  warmupReputation = '100%',
}: Record<string, any>) => ({
  id,
  from_email: email,
  client_id: clientId,
  created_at: createdAt,
  warmup_details: { warmup_reputation: warmupReputation },
});

describe('EmailinfraService', () => {
  let service: EmailinfraService;
  let module: TestingModule;
  let datastore: ReturnType<typeof buildDatastore>;

  const mockSmartlead = (emailAccounts: Record<string, any>[]) => {
    global.fetch = jest.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => emailAccounts,
    })) as any;
  };

  const seed = async (emailAccounts: Record<string, any>[]) => {
    mockSmartlead(emailAccounts.map((account) => smartleadEmailAccount(account)));
    for (const emailAccount of emailAccounts) {
      await service.saveEmailAccount({
        smartleadInboxId: emailAccount.id,
        email: emailAccount.email,
        smartleadClientId: emailAccount.clientId ?? '22',
        campaignIds: emailAccount.campaignIds,
      });
    }
  };

  beforeEach(async () => {
    datastore = buildDatastore();
    module = await Test.createTestingModule({
      imports: [EmailinfraModule],
    })
      .overrideProvider(DatastoreService)
      .useValue(datastore)
      .compile();

    service = module.get<EmailinfraService>(EmailinfraService);
  });

  afterEach(async () => {
    await module.close();
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('saveEmailAccount', () => {
    it('hydrates the creation time and the warm up reputation from smartlead', async () => {
      mockSmartlead([
        smartleadEmailAccount({
          id: '101',
          email: 'ada@sending.trychamp.co',
          createdAt: '2023-05-04T00:00:00.000Z',
          warmupReputation: '96%',
        }),
      ]);

      const emailAccount = await service.saveEmailAccount({
        smartleadInboxId: '101',
        email: 'ada@sending.trychamp.co',
        smartleadClientId: '22',
        tags: ['warmed'],
      });

      expect(emailAccount.smartleadInboxId).toBe('101');
      expect(emailAccount.domain).toBe('sending.trychamp.co');
      expect(emailAccount.createdAt).toBe('2023-05-04T00:00:00.000Z');
      expect(emailAccount.deliverabilityScore).toBe(96);
      expect(emailAccount.deliverability).toBe(DeliverabilityScore.Low);
      expect(emailAccount.tags).toEqual(['warmed']);
      expect(datastore.store).toHaveBeenCalledWith(
        expect.objectContaining({
          context: expect.objectContaining({
            uniqueId: '101',
            documentType: documentType.EMAIL_ACCOUNT,
          }),
        }),
      );
    });

    it('throws when smartlead does not know the inbox', async () => {
      mockSmartlead([]);

      await expect(
        service.saveEmailAccount({
          smartleadInboxId: '404',
          email: 'nobody@sending.trychamp.co',
          smartleadClientId: '22',
        }),
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('lookups', () => {
    beforeEach(async () => {
      await seed([
        { id: '101', email: 'ada@sending.trychamp.co' },
        { id: '102', email: 'grace@sending.trychamp.co' },
        { id: '103', email: 'alan@other.trychamp.co', clientId: '23' },
      ]);
    });

    it('finds an inbox by its smartlead inbox id', async () => {
      const emailAccount = await service.getEmailAccount('102');
      expect(emailAccount.email).toBe('grace@sending.trychamp.co');
    });

    it('finds an inbox by its email', async () => {
      const emailAccount = await service.getEmailAccountByEmail(
        'ada@sending.trychamp.co',
      );
      expect(emailAccount.smartleadInboxId).toBe('101');
    });

    it('finds every inbox of a smartlead client', async () => {
      const emailAccounts =
        await service.getEmailAccountBySmartleadClientId('22');
      expect(emailAccounts.map((account) => account.smartleadInboxId)).toEqual([
        '101',
        '102',
      ]);
    });

    it('throws when the inbox is unknown', async () => {
      await expect(service.getEmailAccount('999')).rejects.toThrow(
        NotFoundException,
      );
    });

    it('lists the inboxes page by page', async () => {
      const firstPage = await service.getAllEmailAccounts({
        page: 0,
        pageSize: 2,
      });
      const secondPage = await service.getAllEmailAccounts({
        page: 1,
        pageSize: 2,
      });

      expect(firstPage.map((account) => account.smartleadInboxId)).toEqual([
        '101',
        '102',
      ]);
      expect(secondPage.map((account) => account.smartleadInboxId)).toEqual([
        '103',
      ]);
      expect(await service.getAllEmailAccounts()).toHaveLength(3);
    });

    it('deletes an inbox', async () => {
      await service.deleteEmailAccount('101');

      expect(datastore.remove).toHaveBeenCalledWith({
        id: '101',
        documentType: documentType.EMAIL_ACCOUNT,
      });
      await expect(service.getEmailAccount('101')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('associateEmailAccountsWithCampaign', () => {
    beforeEach(async () => {
      await seed([
        { id: '101', email: 'ada@sending.trychamp.co' },
        { id: '102', email: 'grace@sending.trychamp.co' },
      ]);
    });

    it('associates the inboxes with the campaign', async () => {
      const emailAccounts = await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['101', '102'],
        campaignId: 'campaign-1',
      });

      expect(emailAccounts.map((account) => account.campaignIds)).toEqual([
        ['campaign-1'],
        ['campaign-1'],
      ]);
      expect(
        (await service.getEmailAccount('101')).numberOfCampaignAssociated,
      ).toBe(1);
    });

    it('is idempotent', async () => {
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['101'],
        campaignId: 'campaign-1',
      });
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['101'],
        campaignId: 'campaign-1',
      });

      const emailAccount = await service.getEmailAccount('101');
      expect(emailAccount.campaignIds).toEqual(['campaign-1']);
      expect(emailAccount.numberOfCampaignAssociated).toBe(1);
    });

    it('rejects the request when one of the inboxes is unknown', async () => {
      await expect(
        service.associateEmailAccountsWithCampaign({
          emailAccountIds: ['101', '999'],
          campaignId: 'campaign-1',
        }),
      ).rejects.toThrow(NotFoundException);

      // None of the inboxes is associated when the request is rejected.
      expect((await service.getEmailAccount('101')).campaignIds).toEqual([]);
    });
  });

  describe('getBestEmailAccountsForCampaign', () => {
    it('returns the healthiest inboxes of the client', async () => {
      mockSmartlead([
        smartleadEmailAccount({
          id: '101',
          email: 'ada@one.trychamp.co',
          warmupReputation: '100%',
        }),
        smartleadEmailAccount({
          id: '102',
          email: 'grace@two.trychamp.co',
          warmupReputation: '99%',
        }),
        smartleadEmailAccount({
          id: '103',
          email: 'alan@three.trychamp.co',
          warmupReputation: '80%',
        }),
        smartleadEmailAccount({
          id: '104',
          email: 'edsger@four.trychamp.co',
          clientId: '23',
          warmupReputation: '100%',
        }),
      ]);
      for (const smartleadInboxId of ['101', '102', '103']) {
        await service.saveEmailAccount({
          smartleadInboxId,
          email: undefined,
          smartleadClientId: '22',
        });
      }
      await service.saveEmailAccount({
        smartleadInboxId: '104',
        email: undefined,
        smartleadClientId: '23',
      });

      const emailAccounts = await service.getBestEmailAccountsForCampaign({
        smartleadClientId: '22',
        campaignId: 'campaign-1',
        totalNumberOfEmailsToSend: 500,
        numberOfDaysInCampaign: 10,
      });

      expect(emailAccounts.map((account) => account.smartleadInboxId)).toEqual([
        '101',
        '102',
      ]);
    });
  });
});

