arguments.newString:
/**
 * A page of inboxes. Without pagination every inbox is returned.
 * Takes either a pagination object or the page and the page size.
 */
async getAllEmailAccounts(
  pagination?: EmailAccountPagination | number,
  pageSize?: number,
): Promise<EmailAccount[]> {
  const requestedPagination: EmailAccountPagination =
    typeof pagination === 'number' ? { page: pagination, pageSize } : pagination;
  const hasPagination =
    requestedPagination &&
    (requestedPagination.page !== undefined ||
      requestedPagination.pageSize !== undefined);
  return this.emailAccounts.findAll(
    hasPagination ? requestedPagination : undefined,
  );
}
